// TH18 v1.00a Stage 5, MainSub02 + MainSub02b (st05.ecl.txt:1076-1100).
// Closure: GirlD01 (S:584-607) -> async GirlD01_at (S:609-655);
//          Cir00 (S:6-26) -> async Cir00_at (S:28-70).
// Source local t0 corresponds to card frame 124 (120-frame buffer + existing
// shell startup, same as th18_s5_b2 / w01).  No source timeout: TIME_LIMIT is
// the local estimate described in report.md.
const TIME_LIMIT: int = 1700;
const TH18_INVERT_RICE: int = 592; // Cir00 etSprite(0,15,2), type15 color2.
const TH18_OVAL: int = 672;        // GirlD01 etSprite(0,20,3), type20 color3.

// GirlD01 S:629-630: WAIT60 then VELTIME(60, target 4.0, keep current angle).
// Source entry speed is 0.6; VELTIME adds (4.0-0.6)/60 per frame.
xformdef D01_VELTIME() {
    wait(60);
    step_speed(4fx, 60 + 65536 * EASE_LINEAR);
}

// S:609-655 GirlD01_at.  wait60, fixed ring mode3 with N=3/6/9/13, alpha=%A,
// speed 0.6, etDist 16 along each bullet angle; %A starts at RANDRAD and is
// advanced by inherited F0 (+/-6deg) after every volley; Easy advances twice.
async sub girl_shot(delta: angle) {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 3;
    var b: int = 30;
    var gap: int = 6;
    if rank == RANK_NORMAL { n = 6; b = 50; gap = 4; }
    if rank == RANK_HARD { n = 9; b = 50; gap = 4; }
    if rank == RANK_LUNATIC { n = 13; b = 50; gap = 4; }
    var a: angle = rand(65536) as angle;
    for v in 0..b {
        for i in 0..n {
            var off: int = (i * 65536) / n;
            var ang: angle = a + (off as angle);
            _ = fire(TH18_OVAL, 3,
                     $self_x + 16fx * cos(ang), $self_y + 16fx * sin(ang),
                     0.6fx, ang, D01_VELTIME, none);
        }
        wait(gap);
        a = a + delta;
        if rank == RANK_EASY { a = a + delta; } // S:649-650 Easy extra step.
    }
}

// S:584-607 GirlD01.  Source boxes 32/24 -> target radius 16/12 (same
// width*0.5 convention as w01); body collision stays active.  moveVel(90,3)
// then moveVelTime(60,1,90,0)=QUAD_IN; after 200 frames moveSpeedTime(120,1,2).
async sub girl_d01(delta: angle) {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn girl_shot(delta);
    wait(200);
    move_speed(120, 2fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

// S:28-70 Cir00_at.  wait20, then 10 loops of aimed shot / random shot at
// speed 1.2; rank changes only the inter-shot wait (80 Easy, 40 otherwise).
async sub cir_shot() {
    wait(20);
    var gap: int = 40;
    if global(GVAR_RANK) == RANK_EASY { gap = 80; }
    for i in 0..10 {
        _ = fire(TH18_INVERT_RICE, 2, $self_x, $self_y, 1.2fx, aim_player(), none, none);
        wait(gap);
        _ = fire(TH18_INVERT_RICE, 2, $self_x, $self_y, 1.2fx,
                 rand(65536) as angle, none, none);
        wait(gap);
    }
}

// S:6-26 Cir00.  Source boxes 28/16 -> target 14/8.  moveVel(90+/-5deg,1.0)
// sets the ABS velocity; moveEllipseRel(0,2deg,10,0,ABS_ANGLE,0) is a fixed-axis
// sine offset on the REL layer (s=0), immediately applied in the setter frame.
// At +200 frames moveSpeedTime(120,0,-1) reverses the ABS scalar speed.
async sub cir(x0: fx, y0: fx) {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    var da: int = ((rand(65536) - 32768) * 910) / 32768; // +/-5deg
    var ax: angle = 90deg + (da as angle);
    var beta: angle = ax;
    var theta: angle = 0deg;
    var px: fx = x0;
    var py: fx = y0;
    var speed: fx = 1fx;
    var sn: fx = sin(theta - beta);
    move_to(0, px - 10fx * sn * sin(beta), py + 10fx * sn * cos(beta), EASE_LINEAR);
    spawn cir_shot();
    var t: int = 0;
    loop {
        wait(1);
        t = t + 1;
        theta = theta + 2deg;
        if t >= 201 {
            var u: int = t - 201;
            if u > 120 { u = 120; }
            speed = 1fx - (2fx * (u as fx)) / 120fx;
        }
        px = px + speed * cos(ax);
        py = py + speed * sin(ax);
        sn = sin(theta - beta);
        move_to(0, px - 10fx * sn * sin(beta), py + 10fx * sn * cos(beta), EASE_LINEAR);
    }
}

// S:1088-1100 MainSub02b.  Six pairs, 80 frames apart; each Cir00 samples its
// own RANDF2 axis at its first run, so creation x is the only value sampled here.
async sub cir_wave() {
    var n: int = 6;
    for i in 0..n {
        var rl: int = rand(65536) - 32768;
        var rr: int = rand(65536) - 32768;
        var xl: fx = -140fx + ((rl as fx) / 32768) * 32fx;
        var xr: fx = 140fx + ((rr as fx) / 32768) * 32fx;
        _ = spawn_enemy(xl, -32fx, 100000, 0, 0, 0, cir(xl, -32fx));
        _ = spawn_enemy(xr, -32fx, 100000, 0, 0, 0, cir(xr, -32fx));
        wait(80);
    }
    loop { wait(1); }
}

// S:1076-1086 MainSub02.  Start 02b async, then create GirlD01 at local 0 and
// 400 with inherited F0=+/-0.10472rad; wait100 and return.
async sub wave() {
    wait(120);
    spawn cir_wave();
    _ = spawn_enemy(0fx, -48fx, 100000, 0, 0, 0, girl_d01(6deg));
    wait(400);
    _ = spawn_enemy(0fx, -48fx, 100000, 0, 0, 0, girl_d01(-6deg));
    wait(100);
    loop { wait(1); }
}

// Practice shell control enemy: fixed at (0,0), no body collision; real wave
// enemies keep their source hurtbox/hitbox.
async sub wave_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 100000, 0, 0, 0, wave_main);
    loop { wait(600); }
}
